"""sklearn.utils.metaestimators — wrappers for meta-estimators."""


def available_if(check):
    """Decorator: a method is available iff ``check(estimator)`` is True.
    The shim attaches it as a property-like wrapper."""
    def _decorator(fn):
        def _wrapper(self, *args, **kwargs):
            if not check(self):
                raise AttributeError(f'{fn.__name__} not available')
            return fn(self, *args, **kwargs)
        return _wrapper
    return _decorator
